using System;using RuningApp;using ShakeGestures;
class Program {static void Check(bool b,string m){if(!b)throw new Exception(m);}static void Main(){var p=new MainPage();var h=ShakeGesturesHelper.Instance;p.StartTest();p.StartTest();Check(h.Subscribers==1,"Repeated Record must have one subscriber");h.Emit();Check(p.ShakeLog.Items.Count==1,"One sensor event must produce one callback");p.StopTest();Check(!h.Active&&h.Subscribers==0,"Stop must release sensor and handler");h.Emit();Check(p.ShakeLog.Items.Count==1,"Stopped page must not receive events");p.StopTest();p.StartTest();Check(h.Active&&h.Subscribers==1,"Restart has one subscriber");p.LeaveTest();Check(!h.Active&&h.Subscribers==0,"Navigation must stop and unsubscribe recording");var next=new MainPage();next.StartTest();Check(h.Subscribers==1,"New page must not retain previous page");h.Emit();Check(p.ShakeLog.Items.Count==1&&next.ShakeLog.Items.Count==1,"Only current page receives events");next.StopTest();Console.WriteLine("PASS: repeated Record, synthetic event, Stop, repeated Stop, restart, navigation and replacement page");}}
